-- Status table for pipeline leaf folders (one row per folder w2026/06/01/<visit>).
-- Generated by st.createSchema('Print',true); equivalent to running
-- st.createSchema() from MATLAB (StatusDB). Idempotent: safe to re-run.
--
--   psql -h euclid -d obs -f schema.sql
--
-- One-time admin setup (as a superuser), adjust names and password:
--   CREATE ROLE pipeline LOGIN PASSWORD '...';
--   CREATE DATABASE obs OWNER pipeline ENCODING 'UTF8' TEMPLATE template0;
-- Read-only users:
--   CREATE ROLE astro_ro LOGIN PASSWORD '...';
--   GRANT SELECT ON visit_status, visit_status_log TO astro_ro;

CREATE TABLE IF NOT EXISTS visit_status ( folder     text COLLATE "C" PRIMARY KEY, status     text        NOT NULL, updated    timestamptz NOT NULL DEFAULT now(), updated_by text        NOT NULL DEFAULT current_user);

CREATE INDEX IF NOT EXISTS visit_status_status_idx ON visit_status (status, folder);

CREATE OR REPLACE FUNCTION visit_status_touch_fn() RETURNS trigger LANGUAGE plpgsql AS $f$ BEGIN NEW.updated := now(); NEW.updated_by := current_user; RETURN NEW; END $f$;

DROP TRIGGER IF EXISTS visit_status_touch ON visit_status;

CREATE TRIGGER visit_status_touch BEFORE UPDATE ON visit_status FOR EACH ROW WHEN (OLD.status IS DISTINCT FROM NEW.status) EXECUTE FUNCTION visit_status_touch_fn();

CREATE TABLE IF NOT EXISTS visit_status_log ( id         bigserial PRIMARY KEY, folder     text COLLATE "C" NOT NULL, old_status text, new_status text, changed    timestamptz NOT NULL DEFAULT now(), changed_by text        NOT NULL DEFAULT current_user);

CREATE INDEX IF NOT EXISTS visit_status_log_folder_idx ON visit_status_log (folder, id);

CREATE OR REPLACE FUNCTION visit_status_log_fn() RETURNS trigger LANGUAGE plpgsql AS $f$ BEGIN IF TG_OP = 'DELETE' THEN   INSERT INTO visit_status_log (folder, old_status, new_status) VALUES (OLD.folder, OLD.status, NULL); ELSIF TG_OP = 'UPDATE' THEN   IF NEW.status IS DISTINCT FROM OLD.status THEN     INSERT INTO visit_status_log (folder, old_status, new_status) VALUES (NEW.folder, OLD.status, NEW.status);   END IF; ELSE   INSERT INTO visit_status_log (folder, old_status, new_status) VALUES (NEW.folder, NULL, NEW.status); END IF; RETURN NULL; END $f$;

DROP TRIGGER IF EXISTS visit_status_log ON visit_status;

CREATE TRIGGER visit_status_log AFTER INSERT OR UPDATE OR DELETE ON visit_status FOR EACH ROW EXECUTE FUNCTION visit_status_log_fn();

